import React, { useCallback, useState } from 'react';
import { useForm, SubmitHandler } from 'react-hook-form';

type FormData = {
  file: FileList; // Тип для поля файла
};

export const FileUpload: React.FC = () => {
  const { register, handleSubmit, setValue } = useForm<FormData>();
  const [file, setFile] = useState<File | null>(null);

  const onDrop = useCallback((acceptedFiles: FileList) => {
    setFile(acceptedFiles[0]);
    setValue('file', acceptedFiles); // Устанавливаем файл в форму
  }, [setValue]);

  const onSubmit: SubmitHandler<FormData> = (data) => {
    const formData = new FormData();
    formData.append('file', data.file[0]); // Используем первый файл из FileList

    // Здесь можно отправить formData на сервер
    console.log('Submitting form', data);
    // Пример: отправка через fetch
    // fetch('/api/upload', {
    //   method: 'POST',
    //   body: formData,
    // });
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      onDrop(files);
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <div
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        style={{
          border: '2px dashed #cccccc',
          padding: '20px',
          textAlign: 'center',
          marginBottom: '20px',
        }}
      >
        {file ? (
          <p>File selected: {file.name}</p>
        ) : (
          <p>Drag & drop a file here, or click to select one</p>
        )}
        <input
          type="file"
          {...register('file')}
          onChange={(e) => {
            if (!e.target.files) return;
            const selectedFile = e.target.files[0];
            setFile(selectedFile);
            setValue('file', e.target.files); // Устанавливаем FileList в форму
          }}
          style={{ display: 'none' }} // Скрываем стандартное поле ввода
        />
        <button type="button" onClick={() => {
          if (document.querySelector('input[type=file]') instanceof HTMLElement) {
  document.querySelector('input[type=file]')?.click()
}
        }
          }>
          Select File
        </button>
      </div>
      <button type="submit">Submit</button>
    </form>
  );
};
